-- Harder Bangla literature questions: poets' birth/death, pen names, works.
insert into public.questions (id, code, subject_id, topic_id, question_en, question_bn, options_en, options_bn,
  correct_option, explanation_en, explanation_bn, difficulty, is_premium, source, is_active)
select s.n, 'NCB-' || lpad(s.n::text, 6, '0'), 15, 10, s.q, s.q, s.o, s.o, s.c, s.e, s.e, 'hard', true, 'Nursing Career BD', true
from (select nextval('public.questions_id_seq') as n, v.* from (values
('রবীন্দ্রনাথ ঠাকুর কত সালে জন্মগ্রহণ করেন?', array['১৮৬৩','১৮৫৯','১৮৬৬','১৮৬১'], 3, 'সঠিক উত্তর: ১৮৬১। রবীন্দ্রনাথ ঠাকুর ৭ মে ১৮৬১ (২৫ বৈশাখ ১২৬৮) কলকাতার জোড়াসাঁকোতে জন্মগ্রহণ করেন এবং ৭ আগস্ট ১৯৪১ (২২ শ্রাবণ ১৩৪৮) মৃত্যুবরণ করেন।'),
('রবীন্দ্রনাথ ঠাকুর বাংলা কোন তারিখে মৃত্যুবরণ করেন?', array['১২ ভাদ্র','১১ জ্যৈষ্ঠ','২২ শ্রাবণ','২৫ বৈশাখ'], 2, 'সঠিক উত্তর: ২২ শ্রাবণ। রবীন্দ্রনাথের মৃত্যু: ২২ শ্রাবণ ১৩৪৮ (৭ আগস্ট ১৯৪১)। ২৫ বৈশাখ তাঁর জন্মদিন; ১১ জ্যৈষ্ঠ নজরুলের জন্মদিন, ১২ ভাদ্র নজরুলের মৃত্যুদিন।'),
('রবীন্দ্রনাথ ঠাকুরের প্রথম প্রকাশিত কাব্যগ্রন্থ কোনটি?', array['বনফুল','সন্ধ্যাসংগীত','মানসী','কবিকাহিনী'], 3, 'সঠিক উত্তর: কবিকাহিনী। রবীন্দ্রনাথের প্রথম প্রকাশিত কাব্যগ্রন্থ ''কবিকাহিনী'' (১৮৭৮)।'),
('রবীন্দ্রনাথ ঠাকুর কোন গ্রন্থের জন্য ১৯১৩ সালে নোবেল পুরস্কার পান?', array['সোনার তরী','বলাকা','Song Offerings (গীতাঞ্জলি)','গীতিমাল্য'], 2, 'সঠিক উত্তর: Song Offerings (গীতাঞ্জলি)। গীতাঞ্জলির ইংরেজি অনুবাদ ''Song Offerings''-এর জন্য রবীন্দ্রনাথ ১৯১৩ সালে সাহিত্যে নোবেল পুরস্কার পান।'),
('''ভানুসিংহ ঠাকুর'' কার ছদ্মনাম?', array['দ্বিজেন্দ্রলাল রায়','সত্যেন্দ্রনাথ দত্ত','বিহারীলাল চক্রবর্তী','রবীন্দ্রনাথ ঠাকুর'], 3, 'সঠিক উত্তর: রবীন্দ্রনাথ ঠাকুর। রবীন্দ্রনাথ ''ভানুসিংহ ঠাকুর'' ছদ্মনামে ''ভানুসিংহ ঠাকুরের পদাবলী'' রচনা করেন।'),
('কাজী নজরুল ইসলামের জন্ম তারিখ কোনটি?', array['২৫ মে ১৮৯৯','২৯ আগস্ট ১৮৯৯','২৪ মে ১৯০১','২৪ মে ১৮৯৯'], 3, 'সঠিক উত্তর: ২৪ মে ১৮৯৯। কাজী নজরুল ইসলাম ২৪ মে ১৮৯৯ (১১ জ্যৈষ্ঠ ১৩০৬) পশ্চিমবঙ্গের বর্ধমান জেলার চুরুলিয়া গ্রামে জন্মগ্রহণ করেন।'),
('কাজী নজরুল ইসলাম কোন তারিখে মৃত্যুবরণ করেন?', array['২৯ আগস্ট ১৯৭৫','২৭ আগস্ট ১৯৭৬','২৯ আগস্ট ১৯৭৬','১৩ মার্চ ১৯৭৬'], 2, 'সঠিক উত্তর: ২৯ আগস্ট ১৯৭৬। নজরুল ২৯ আগস্ট ১৯৭৬ (১২ ভাদ্র ১৩৮৩) ঢাকায় মৃত্যুবরণ করেন। ১৩ মার্চ ১৯৭৬ জসীমউদ্দীনের মৃত্যুদিন।'),
('কাজী নজরুল ইসলামের জন্মস্থান কোথায়?', array['ত্রিশাল, ময়মনসিংহ','দৌলতপুর, কুমিল্লা','চুরুলিয়া, বর্ধমান','দরিরামপুর, ময়মনসিংহ'], 2, 'সঠিক উত্তর: চুরুলিয়া, বর্ধমান। নজরুলের জন্ম বর্ধমানের চুরুলিয়ায়। ময়মনসিংহের ত্রিশালের দরিরামপুর স্কুলে তিনি পড়াশোনা করেছিলেন।'),
('কাজী নজরুল ইসলামের প্রথম প্রকাশিত কাব্যগ্রন্থ কোনটি?', array['অগ্নিবীণা','দোলনচাঁপা','বিষের বাঁশী','সঞ্চিতা'], 0, 'সঠিক উত্তর: অগ্নিবীণা। নজরুলের প্রথম প্রকাশিত কাব্যগ্রন্থ ''অগ্নিবীণা'' (১৯২২)।'),
('কাজী নজরুল ইসলাম সম্পাদিত অর্ধসাপ্তাহিক পত্রিকা কোনটি?', array['সওগাত','মোসলেম ভারত','ধূমকেতু','লাঙল'], 2, 'সঠিক উত্তর: ধূমকেতু। নজরুল ১৯২২ সালে অর্ধসাপ্তাহিক ''ধূমকেতু'' প্রকাশ করেন।'),
('মাইকেল মধুসূদন দত্তের জন্মস্থান কোথায়?', array['লাহিনীপাড়া, কুষ্টিয়া','শিলাইদহ, কুষ্টিয়া','জোড়াসাঁকো, কলকাতা','সাগরদাঁড়ি, যশোর'], 3, 'সঠিক উত্তর: সাগরদাঁড়ি, যশোর। মধুসূদন দত্ত ২৫ জানুয়ারি ১৮২৪ যশোরের সাগরদাঁড়িতে জন্মগ্রহণ করেন এবং ২৯ জুন ১৮৭৩ কলকাতায় মারা যান।'),
('মাইকেল মধুসূদন দত্ত কত সালে মৃত্যুবরণ করেন?', array['১৮৮১','১৮৭৫','১৮৭১','১৮৭৩'], 3, 'সঠিক উত্তর: ১৮৭৩। মধুসূদন দত্তের মৃত্যু ২৯ জুন ১৮৭৩, কলকাতায়।'),
('''মেঘনাদবধ কাব্য'' কোন ছন্দে রচিত?', array['পয়ার','স্বরবৃত্ত','অমিত্রাক্ষর','মাত্রাবৃত্ত'], 2, 'সঠিক উত্তর: অমিত্রাক্ষর। মধুসূদন দত্তের ''মেঘনাদবধ কাব্য'' (১৮৬১) অমিত্রাক্ষর ছন্দে রচিত।'),
('জীবনানন্দ দাশের মৃত্যু কীভাবে হয়?', array['নৌকাডুবিতে','হৃদরোগে','যক্ষ্মা রোগে','ট্রাম দুর্ঘটনায়'], 3, 'সঠিক উত্তর: ট্রাম দুর্ঘটনায়। ১৪ অক্টোবর ১৯৫৪ কলকাতায় ট্রাম দুর্ঘটনায় আহত হয়ে ২২ অক্টোবর ১৯৫৪ জীবনানন্দ দাশ মারা যান।'),
('জীবনানন্দ দাশ কোথায় জন্মগ্রহণ করেন?', array['বরিশাল','ফরিদপুর','যশোর','খুলনা'], 0, 'সঠিক উত্তর: বরিশাল। জীবনানন্দ দাশ ১৭ ফেব্রুয়ারি ১৮৯৯ বরিশালে জন্মগ্রহণ করেন।'),
('জীবনানন্দ দাশের প্রথম কাব্যগ্রন্থ কোনটি?', array['রূপসী বাংলা','ঝরা পালক','বনলতা সেন','ধূসর পাণ্ডুলিপি'], 1, 'সঠিক উত্তর: ঝরা পালক। জীবনানন্দ দাশের প্রথম কাব্যগ্রন্থ ''ঝরা পালক'' (১৯২৭)।'),
('মাত্র ২১ বছর বয়সে যক্ষ্মা রোগে মারা যান কোন কবি?', array['জীবনানন্দ দাশ','হেলাল হাফিজ','আবুল হাসান','সুকান্ত ভট্টাচার্য'], 3, 'সঠিক উত্তর: সুকান্ত ভট্টাচার্য। সুকান্ত ভট্টাচার্য (জন্ম ১৫ আগস্ট ১৯২৬, মৃত্যু ১৩ মে ১৯৪৭) যক্ষ্মায় মারা যান।'),
('সুকান্ত ভট্টাচার্যের প্রথম কাব্যগ্রন্থ কোনটি?', array['ঘুম নেই','অভিযান','ছাড়পত্র','পূর্বাভাস'], 2, 'সঠিক উত্তর: ছাড়পত্র। সুকান্তের প্রথম কাব্যগ্রন্থ ''ছাড়পত্র'' (১৯৪৭)।'),
('পল্লীকবি জসীমউদ্দীনের জন্মস্থান কোথায়?', array['সাগরদাঁড়ি, যশোর','পায়রাবন্দ, রংপুর','চুরুলিয়া, বর্ধমান','তাম্বুলখানা, ফরিদপুর'], 3, 'সঠিক উত্তর: তাম্বুলখানা, ফরিদপুর। জসীমউদ্দীন ১ জানুয়ারি ১৯০৩ ফরিদপুরের তাম্বুলখানা গ্রামে (মাতুলালয়ে) জন্মগ্রহণ করেন।'),
('পল্লীকবি জসীমউদ্দীন কত সালে মৃত্যুবরণ করেন?', array['১৯৭৬','১৯৭১','১৯৭৪','১৯৭৮'], 0, 'সঠিক উত্তর: ১৯৭৬। জসীমউদ্দীনের মৃত্যু ১৩ মার্চ ১৯৭৬, ঢাকায়।'),
('জসীমউদ্দীনের ''নকশী কাঁথার মাঠ'' কত সালে প্রকাশিত হয়?', array['১৯২৯','১৯৩৩','১৯৩৯','১৯২৭'], 0, 'সঠিক উত্তর: ১৯২৯। ''নকশী কাঁথার মাঠ'' ১৯২৯ সালে প্রকাশিত হয়।'),
