('''জমিদার দর্পণ'' নাটকের রচয়িতা কে?', array['মাইকেল মধুসূদন দত্ত','মুনীর চৌধুরী','দীনবন্ধু মিত্র','মীর মশাররফ হোসেন'], 3, 'সঠিক উত্তর: মীর মশাররফ হোসেন। ''জমিদার দর্পণ'' মীর মশাররফ হোসেনের নাটক।'),
('''নীলদর্পণ'' নাটকের রচয়িতা কে?', array['মীর মশাররফ হোসেন','গিরিশচন্দ্র ঘোষ','দীনবন্ধু মিত্র','মাইকেল মধুসূদন দত্ত'], 2, 'সঠিক উত্তর: দীনবন্ধু মিত্র। নীলচাষিদের ওপর অত্যাচার নিয়ে দীনবন্ধু মিত্র ''নীলদর্পণ'' (১৮৬০) রচনা করেন।'),
