('''বনফুল'' কার ছদ্মনাম?', array['প্রমথ চৌধুরী','বলাইচাঁদ মুখোপাধ্যায়','অন্নদাশঙ্কর রায়','সমরেশ বসু'], 1, 'সঠিক উত্তর: বলাইচাঁদ মুখোপাধ্যায়। বলাইচাঁদ মুখোপাধ্যায়ের ছদ্মনাম ''বনফুল''।'),
