('''মজলুম আদিব'' ছদ্মনামটি কার?', array['শামসুর রাহমান','আল মাহমুদ','সৈয়দ শামসুল হক','নির্মলেন্দু গুণ'], 0, 'সঠিক উত্তর: শামসুর রাহমান। মুক্তিযুদ্ধের সময় শামসুর রাহমান ''মজলুম আদিব'' ছদ্মনামে লিখতেন।'),
