('''সোনালী কাবিন'' কার রচনা?', array['শামসুর রাহমান','আল মাহমুদ','শহীদ কাদরী','সৈয়দ শামসুল হক'], 1, 'সঠিক উত্তর: আল মাহমুদ। ''সোনালী কাবিন'' আল মাহমুদের কাব্যগ্রন্থ।'),
('আল মাহমুদ কত সালে মৃত্যুবরণ করেন?', array['২০১৭','২০১৯','২০২১','২০১৬'], 1, 'সঠিক উত্তর: ২০১৯। আল মাহমুদের জন্ম ১১ জুলাই ১৯৩৬, মৃত্যু ১৫ ফেব্রুয়ারি ২০১৯।'),
