('হুমায়ূন আহমেদের প্রথম উপন্যাস কোনটি?', array['মধ্যাহ্ন','নন্দিত নরকে','শঙ্খনীল কারাগার','জোছনা ও জননীর গল্প'], 1, 'সঠিক উত্তর: নন্দিত নরকে। হুমায়ূন আহমেদের প্রথম উপন্যাস ''নন্দিত নরকে'' (১৯৭২)।'),
